package com.projectseele.world;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.world.phys.*;
import com.projectseele.world.NervAirTransportManifestR52.*;

/** Actual aircraft/rotor source collision fixtures, no world or native actor. */
public final class FlightCollisionReuseEvidenceR52 {
 private static int checks;
 private static void check(boolean okay,String reason){checks++;if(!okay)throw new AssertionError(reason);}
 public static void main(String[] args)throws Exception {
  var air=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonObject();var hashes=new HashMap<String,String>();air.getAsJsonObject("mesh_sources").entrySet().forEach(e->hashes.put(e.getKey(),e.getValue().getAsString()));var geometry=NervAirframeGeometryR52.loadClasspath(hashes);
  var frame=new Frame(new RigidTransform(new Vec3(100,512,100),0,0,0,1),null,new Rig(112,0,1));var to=new Frame(new RigidTransform(new Vec3(101,512,100),0,0,0,1),null,frame.rig());
  var oldBounds=NervFlightProofR52.sourceEnvelopesR52(geometry,null,frame,to,0,1,false);var oldSweep=geometry.sweep(frame,to,List.of(),List.of(),0,1,.005);var prepared=NervFlightProofR52.prepareSourceSweepR52(null,geometry,null,frame,to,0,1,false);check(oldBounds.equals(prepared.envelopes())&&oldSweep.envelopes().equals(prepared.sourceSweepR52().envelopes()),"Same actual source/time endpoints changed after preparation reuse");check(!prepared.matchesR52(null,geometry,null,frame,to,0,1,false),"Offline source-only preparation granted live motion admission");
  var first=geometry.bodyMesh().triangles();var point=frame.plane().transformPoint(new Vec3(first[0],first[1],first[2]));var thin=new AABB(point.x-.0000005,point.y-.003,point.z-.003,point.x+.0000005,point.y+.003,point.z+.003);var neighbor=thin.move(.0000001,0,0);check(oldSweep.intersects(thin)&&prepared.sourceSweepR52().intersects(thin),"Micrometre thin wall was lost");
  var ledger=new NervFlightProofR52.ExactBlockObstaclesR52();var clearBox=new AABB(2000,2000,2000,2001,2001,2001);int oldNarrow=0,newNarrow=0;for(int i=0;i<200;i++){oldNarrow++;check(!oldSweep.intersects(clearBox),"Far actual block unexpectedly intersects aircraft");if(ledger.first(clearBox)){newNarrow++;check(!prepared.sourceSweepR52().intersects(clearBox),"Exact duplicate reduction changed clear result");}}check(ledger.observations()==200&&ledger.narrowPhases()==1&&newNarrow==1,"Native candidate observations were skipped or duplicate narrow checks remained");
  check(ledger.first(thin)&&ledger.first(neighbor)&&!ledger.first(thin),"Near neighbors were merged or exact duplicate not recognized");check(prepared.sourceSweepR52().intersects(neighbor)==oldSweep.intersects(neighbor),"Neighbor thin-wall verdict changed");
  var a=new Vec3(first[0],first[1],first[2]);var b=new Vec3(first[3],first[4],first[5]);var c=new Vec3(first[6],first[7],first[8]);var normal=b.subtract(a).cross(c.subtract(a)).normalize();var obstacleFrom=new RigidTransform(point.add(normal.scale(10)),0,0,0,1);var obstacleTo=new RigidTransform(point.add(normal.scale(-10)),0,0,0,1);boolean before=oldSweep.intersects(geometry.rotorMesh(0),obstacleFrom,obstacleTo),after=prepared.sourceSweepR52().intersects(geometry.rotorMesh(0),obstacleFrom,obstacleTo);check(before&&after,"Actual moving rotor mechanism swept contact was lost after block-box dedup");
  int comparisons=0;for(var boxes:List.of(List.<AABB>of(),List.of(thin),List.of(neighbor),List.of(clearBox),List.of(thin,thin,neighbor))){boolean original=true;for(var envelope:prepared.envelopes())for(var box:boxes)if(envelope.intersects(box)&&prepared.sourceSweepR52().intersects(box))original=false;var exact=new NervFlightProofR52.ExactBlockObstaclesR52();var grouped=BoundedNativeCollisionGroupsR52.clear(prepared.envelopes(),box->true,query->boxes.stream().filter(query::intersects).toList(),(piece,box)->exact.first(box)&&prepared.sourceSweepR52().intersects(box));check(original==grouped.clear(),"Grouped native reads changed complete actual aircraft source verdict");comparisons++;}
  var fallback=BoundedNativeCollisionGroupsR52.clear(List.of(new AABB(0,0,0,1,1,1),new AABB(2,0,0,3,1,1)),box->box.maxX-box.minX<=1,query->List.of(),(piece,box)->false);check(fallback.clear()&&fallback.originalFallbackReads()==2&&fallback.groupedReads()==0,"Unreadable merged bridge failed to retain original readable boxes");
  var report=new LinkedHashMap<String,Object>();report.put("world_written",false);report.put("native_accepted",false);report.put("checks",checks);report.put("actual_air_source_sha",geometry.fingerprint());report.put("same_source_endpoints_rotor_bounds",true);report.put("sweep_constructions_per_source_plus_check_before",2);report.put("sweep_constructions_per_prepared_source_plus_check_after",1);report.put("duplicate_block_candidate_observations",200);report.put("duplicate_full_sweep_narrow_phases_before",oldNarrow);report.put("duplicate_full_sweep_narrow_phases_after",newNarrow);report.put("micrometre_thin_wall_preserved",true);report.put("near_neighbor_box_not_merged",true);report.put("actual_moving_rotor_mechanism_contact_preserved",true);report.put("grouped_original_exact_source_verdict_comparisons",comparisons);report.put("unreadable_group_original_boxes_fallback",true);report.put("scope","Exact production obstacle ledger and actual aircraft/rotor source fixtures; live native/Forge queries retained and optionally grouped, live native world not claimed");Files.writeString(Path.of(args[1]),new GsonBuilder().setPrettyPrinting().create().toJson(report));System.out.println("Flight source reuse/obstacle semantics PASS checks="+checks+" source-builds2->1 duplicate-narrow200->1");
 }
}
